export const getPageVisibilityRules = ({
  isLvAdmin,
  isInternalAgent,
  isGuardianAgentLogin,
  lv_details,
}) => ({
  bank_account: () => !isLvAdmin,
  my_downline: () => !lv_details,
  change_pin: () => !isGuardianAgentLogin,
  login_as_agent: () => {
    const rolesAllowed = [isLvAdmin, isInternalAgent && !isGuardianAgentLogin]
    return rolesAllowed.some(Boolean)
  },
})
