import React, { useCallback, useEffect, useState } from 'react'
import { connect } from 'react-redux'
import get from 'lodash/get'
import { Container, Button, CustomText } from '../../../../components'
import { ProfileWrapper } from './index.style'
import { DANGER, INFO, LOGOUT_AGENT_GOLD, YELLOW_REACT_POLYGON } from '../../../../images'
import { AgentColorPallette } from '../../../../configs/colorPallete'
import AuthActions from '../../../../redux/auth/action'
import { Row, DisplayFlexRCSB, DisplayCircleIcon } from '../../../../commonStyle/index.style'
import { PROFILE_PAGES } from '../constants/index'
import { LANG_STRINGS } from '../../../../lang'
import ToolTip from '../../../../components/ToolTip'
import WarningModal from '../../../../components/WarningModal'
import WarningNotification from '../../../../components/WarningNotification'
import ProfileInfoHeader from '../components/ProfileInfoHeader/index'
import {
  useGetAgentDetails,
  useAgentLogout,
  useUpdateGlobal,
} from '../../../../state/globalState/hooks/useGlobalContext'
import { LOGIN_AS_GURDIAN } from '../../../../constants/cookies'
import { webengageLogOutEvent } from '../../../../bridges/android'
import { webengageLogOutEventInIos } from '../../../../bridges/iOS'
import { logoutWebEngageUser } from '../../../../hooks/trackers/webengage'
import { isIos } from '../../../../helpers/utility'
import { checkIsLvAdmin } from '../../../../helpers/checkAgentTags'
import { getPageVisibilityRules } from './helpers'

const { logoutGuardian, resetAuthStore } = AuthActions

function ProfileContainer(props) {
  const { guardianLogOutStatus, resetAuthStore } = props
  const [, dispatchGlobal] = useUpdateGlobal()
  const [
    {
      isStaffAgent,
      isHideAgentBadges,
      agentDetails,
      isGuardianAgentLogin,
      isInternalAgent,
      isRetailStaffAgent,
      isAggregatorStaffAgent,
      fcmToken = '',
    },
  ] = useUpdateGlobal()

  const getProfileSections = useCallback(() => {
    const rules = getPageVisibilityRules({
      isLvAdmin: checkIsLvAdmin(agentDetails),
      isInternalAgent,
      isGuardianAgentLogin,
      lv_details: agentDetails.lv_details,
    })
    return PROFILE_PAGES.filter((page) => {
      const rule = rules[page.id]
      return rule ? rule() : true
    })
  }, [isGuardianAgentLogin, isInternalAgent, agentDetails])

  const [, getAgentDetailsRequest] = useGetAgentDetails()
  const [, agentLogoutRequest] = useAgentLogout()

  const [warningModal, setWarningModal] = useState({
    isVisible: false,
    warningTitle: LANG_STRINGS.partnerLogoutSuccessfully,
    warningOkText: LANG_STRINGS.okay,
    warningIcon: LOGOUT_AGENT_GOLD,
    warning: '',
  })
  const [profilePages, setProfilePages] = useState(getProfileSections())

  useEffect(() => {
    setProfilePages(getProfileSections())
  }, [getProfileSections])

  useEffect(() => {
    if (isRetailStaffAgent || isAggregatorStaffAgent) {
      setProfilePages((p) => p.filter((item) => item.name !== LANG_STRINGS.bankAccount))
    }
  }, [isRetailStaffAgent, isAggregatorStaffAgent])

  useEffect(() => {
    if (guardianLogOutStatus === 'success') {
      getAgentDetailsRequest({
        headers: {
          [LOGIN_AS_GURDIAN]: '',
        },
      })
      resetAuthStore(['guardianLogOutStatus'])
    }
  }, [guardianLogOutStatus, getAgentDetailsRequest, resetAuthStore, dispatchGlobal])

  const handlePageClick = (page) => {
    props.history.push(page.path)
  }

  const handleWarningModal = () => {
    setWarningModal((prev) => ({
      ...warningModal,
      isVisible: !prev.isVisible,
      warning: `
        ${LANG_STRINGS.congratsYouLogoutFromPartner}
        <span class='golden-text'>${get(props, 'agentDetails.name', '')}</span>
      `,
    }))
  }

  const handleLogout = () => {
    logoutWebEngageUser()
    if (isGuardianAgentLogin) {
      // true => to handle the redirection to dashboard
      props.logoutGuardian(true)
      dispatchGlobal({
        headers: { 'Content-Type': 'application/json' },
        isHideAgentBadges: false,
      })
      handleWarningModal()
      return
    }
    agentLogoutRequest({
      fcmToken,
    })
    if (isIos()) {
      webengageLogOutEventInIos()
    } else {
      webengageLogOutEvent()
    }
  }

  const renderTemplate = (profile, index, isKtpVerified) => {
    const isShowStaffOption =
      agentDetails?.is_allowed_staff || agentDetails?.previously_active_staff

    if (isStaffAgent && ['/refer-earn', '/my-downline', '/staff/list'].includes(profile.path)) {
      return null
    }
    if (!isShowStaffOption && profile.path === '/staff/list') {
      return null
    }
    return (
      <DisplayFlexRCSB
        className="pages-container "
        key={`profile_${index}`}
        data-gtm-element-id={profile.id}
        onClick={() => handlePageClick(profile)}
      >
        <Row data-gtm-element-id={profile.id}>
          <div className="profile-pages-icon" data-gtm-element-id={profile.id}>
            <img src={profile.imgUrl} alt="" />
          </div>
          <CustomText
            color={AgentColorPallette.black}
            size="14px"
            weight={700}
            data-gtm-element-id={profile.id}
          >
            {profile.name}
            {profile.isNew && <span className="new">{LANG_STRINGS.new}</span>}
          </CustomText>
        </Row>
        {!index && isKtpVerified === false && <img src={DANGER} alt="" />}
        {profile.path === '/dependent/agents' && (
          <ToolTip
            dataView={<CustomText>{LANG_STRINGS.youCanEnterAsPartnerStatement}</CustomText>}
            className="login-agent-info"
          >
            <DisplayCircleIcon>
              <img src={INFO} alt="" />
            </DisplayCircleIcon>
          </ToolTip>
        )}
      </DisplayFlexRCSB>
    )
  }

  const { isVisible, warningTitle, warningOkText, warningIcon, warning } = warningModal
  const { agent_code: agentCode, name, is_ktp_verified: isKtpVerified } = agentDetails

  return (
    <Container title={LANG_STRINGS.myAccount} showOJKText>
      <ProfileWrapper>
        <WarningNotification
          isStaffAgent={isStaffAgent}
          getAgentDetailData={agentDetails}
        />
        <ProfileInfoHeader
          name={name}
          agentCode={agentCode}
          bgImg={YELLOW_REACT_POLYGON}
          height="117px"
          isHideAgentBadges={isHideAgentBadges}
          showNameSection
        />
        {profilePages.map((profile, index) => renderTemplate(profile, index, isKtpVerified))}
        <div className="exit-button">
          <Button
            backgroundColor={AgentColorPallette.saturatedGrey}
            color={AgentColorPallette.fontGrey}
            onClick={handleLogout}
            className="box-shadow"
          >
            {isGuardianAgentLogin ? LANG_STRINGS.logoutAsPartner : 'keluar'}
          </Button>
        </div>
      </ProfileWrapper>
      {isVisible && (
        <WarningModal
          showModal={isVisible}
          hideCloseBtn
          warning={warning}
          title={warningTitle}
          okText={warningOkText}
          icon={warningIcon}
          onOk={handleWarningModal}
          onClose={handleWarningModal}
        />
      )}
    </Container>
  )
}

export default connect(
  (state) => ({
    guardianLogOutStatus: state.Auth.guardianLogOutStatus,
  }),
  {
    logoutGuardian,
    resetAuthStore,
  }
)(ProfileContainer)
