import { useState, useEffect, useCallback } from 'react'
import { Row } from '../../../../../commonStyle/index.style'
import { CustomText } from '../../../../../components'
import { AgentColorPallette } from '../../../../../configs/colorPallete'
import { useGlobalContextValue } from '../../../../../contextProvider/GlobalContext'
// import { ImageUrl } from '../../../../../images'
import { LANG_STRINGS } from '../../../../../lang'
import { ProfileInfoHeaderStyle } from './index.style'
import { useGetAgentGWP } from '../../../../../state/globalState/hooks/useGlobalContext'
import BottomSheetSelectMonths from '../../../../../components/BottomSheetSelectMonth'
import { formatMoney, mapNumberToMonth } from '../../../../../helpers/utility'
import moment from 'moment'
// import AgentBadgeInfo from '../../../../../components/AgentBadgeInfo'

function ProfileInfoHeader (props) {
  const { height } = props
  const [{ isHideAgentBadges }] = useGlobalContextValue()
  const [showMonthModal, setShowMonthModal] = useState(false)
  // const [{ getAgentBadgesData = {} }, getAgentBadgesRequest] = useGetAgentBadges()
  const [{ getAgentGwpData = {} }, getAgentGwpRequest] = useGetAgentGWP()
  const [month, setMonth] = useState(moment().month())
  const [year, setYear] = useState(moment().year())

  useEffect(() => {
    // getAgentBadgesRequest()
    getAgentGwpRequest({ agent_code: props.agentCode })
  }, [getAgentGwpRequest, props.agentCode])

  const handleCloseMonthModal = useCallback(() => {
    setShowMonthModal(false)
  }, [])

  return (
    <ProfileInfoHeaderStyle
      // bgImg={isHideAgentBadges && bgImg}
      height={isHideAgentBadges && height}
      // isCenterAlign={!showNameSection}
    >
      <div className='top-border'>
        {
          // (isHideAgentBadges !== true) ? <AgentBadgeInfo agentName={name} /> :
          (
            <Row className='user-icon-name-box' align='center' justify='space-between'>
              {/* <DisplayCircleIcon width='60px' height='60px' bgColor={AgentColorPallette.white}>
                <img className='user-icon' src={ImageUrl.userIcon} alt='User' />
              </DisplayCircleIcon>&nbsp;&nbsp;&nbsp; */}
              <div>
                <CustomText size='14px' color={AgentColorPallette.black} weight={800}>
                  {LANG_STRINGS.gwp}
                </CustomText>
                <CustomText size='16px' color={AgentColorPallette.black} weight={800}>
                  {formatMoney(getAgentGwpData?.paid_gwp, 0)}
                </CustomText>
              </div>
              <div>
                <CustomText size='14px' color={AgentColorPallette.black} weight={800} className='float-right'>
                  {LANG_STRINGS.chooseMonth}
                </CustomText>
                <CustomText
                  size='16px'
                  color={AgentColorPallette.black}
                  weight={800}
                  onClick={() => setShowMonthModal(true)}
                >
                  {mapNumberToMonth(month, true)} {year}
                  <i
                    className='fas fa-triangle-down '
                  />
                </CustomText>
              </div>
            </Row>
          )
        }
      </div>
      {
        showMonthModal && (
          <BottomSheetSelectMonths
            show={showMonthModal}
            onClose={handleCloseMonthModal}
            month={month}
            year={year}
            setMonth={setMonth}
            setYear={setYear}
            agentGwpRequest={getAgentGwpRequest}
            agentCode={props.agentCode}
          />
        )
      }
    </ProfileInfoHeaderStyle>
  )
}

export default ProfileInfoHeader
